import assert from "node:assert/strict";
import { after, before, describe, it } from "node:test";
import { startServer, type Running } from "./helpers/server.ts";

interface Task {
  id: number;
  title: string;
}

interface ApiError {
  error: { code: string; message: string };
}

function post(server: Running, body: string): Promise<Response> {
  return fetch(`${server.baseUrl}/api/tasks`, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body,
  });
}

function postTitle(server: Running, title: unknown): Promise<Response> {
  return post(server, JSON.stringify({ title }));
}

async function listTasks(server: Running): Promise<Task[]> {
  const response = await fetch(`${server.baseUrl}/api/tasks`);
  return ((await response.json()) as { tasks: Task[] }).tasks;
}

async function assertRejected(
  server: Running,
  response: Response,
  code: string,
  message: string,
): Promise<void> {
  assert.equal(response.status, 400);
  const body = (await response.json()) as ApiError;
  assert.deepEqual(body, { error: { code, message } });
  assert.deepEqual(await listTasks(server), [], "a rejected request stores nothing");
}

describe("SL-004 reject empty and over-long titles", () => {
  describe("AC-1: a title that is empty after trimming", () => {
    let server: Running;
    before(async () => {
      server = await startServer();
    });
    after(async () => {
      await server?.stop();
    });

    for (const [name, title] of [
      ["an empty string", ""],
      ["spaces only", "     "],
      ["tabs and newlines only", " \t\n "],
    ] as const) {
      it(`AC-1: ${name} answers 400 validation_failed 'A title is required.' and stores nothing`, async () => {
        await assertRejected(
          server,
          await postTitle(server, title),
          "validation_failed",
          "A title is required.",
        );
      });
    }

    for (const [name, title] of [
      ["missing", undefined],
      ["a number", 42],
      ["null", null],
      ["an array", ["Buy milk"]],
    ] as const) {
      it(`AC-1: a title that is ${name} answers 400 'Title must be a string.' and stores nothing`, async () => {
        await assertRejected(
          server,
          await postTitle(server, title),
          "validation_failed",
          "Title must be a string.",
        );
      });
    }

    it("AC-1: a body that is not JSON answers 400 invalid_json and stores nothing", async () => {
      await assertRejected(
        server,
        await post(server, "{not json"),
        "invalid_json",
        "The request body is not valid JSON.",
      );
    });

    it("AC-1: a JSON body that is not an object answers 400 'Title must be a string.'", async () => {
      await assertRejected(
        server,
        await post(server, "null"),
        "validation_failed",
        "Title must be a string.",
      );
    });
  });

  describe("AC-2: a title longer than 500 characters", () => {
    let server: Running;
    before(async () => {
      server = await startServer();
    });
    after(async () => {
      await server?.stop();
    });

    it("AC-2: 501 characters answers 400 with the too-long message and stores nothing", async () => {
      await assertRejected(
        server,
        await postTitle(server, "a".repeat(501)),
        "validation_failed",
        "The title is too long (maximum 500 characters).",
      );
    });

    it("AC-2: the length is counted after trimming, so 501 characters plus outer spaces is rejected", async () => {
      await assertRejected(
        server,
        await postTitle(server, `  ${"a".repeat(501)}  `),
        "validation_failed",
        "The title is too long (maximum 500 characters).",
      );
    });

    it("AC-2: exactly 500 characters is accepted", async () => {
      const response = await postTitle(server, "a".repeat(500));
      assert.equal(response.status, 201);
      const { task } = (await response.json()) as { task: Task };
      assert.equal(task.title.length, 500);
      assert.equal((await listTasks(server)).length, 1);
    });

    it("AC-2: 500 characters plus outer spaces is accepted and stored trimmed", async () => {
      const response = await postTitle(server, ` ${"b".repeat(500)} `);
      assert.equal(response.status, 201);
      const { task } = (await response.json()) as { task: Task };
      assert.equal(task.title, "b".repeat(500));
    });

    it("AC-2: a rejected title leaves the earlier tasks unchanged", async () => {
      const before = await listTasks(server);
      await postTitle(server, "c".repeat(501));
      await postTitle(server, "   ");
      assert.deepEqual(await listTasks(server), before);
    });
  });

  describe("AC-1 and AC-2: the page shows the reason", () => {
    let server: Running;
    let html: string;
    let script: string;

    before(async () => {
      server = await startServer();
      html = await (await fetch(`${server.baseUrl}/`)).text();
      script = await (await fetch(`${server.baseUrl}/app.js`)).text();
    });
    after(async () => {
      await server?.stop();
    });

    it("AC-1: has an element #form-message with role=alert for the message", () => {
      assert.match(html, /<[a-z]+(?=[^>]*id=["']form-message["'])(?=[^>]*role=["']alert["'])[^>]*>/);
    });

    it("AC-1: the page script writes the server's error.message into #form-message with textContent", () => {
      assert.match(script, /form-message/);
      assert.match(script, /error\.message/);
      assert.match(script, /\.ok\b/);
      assert.doesNotMatch(script, /innerHTML/);
    });
  });
});
EOF
